using System.Linq;
using Axicultus.Module;
using FluentAssertions;
using Xunit;

namespace Axicultus.Wpf.Tests.Library;

// Pins how PowerPointSourceFiles reads the hymn number and the title from a file name
// (the HymnPrefix regex), branch by branch. The regex is source-generated by the targeting
// pack's generator, so these tests guard the generated code when the target framework changes.
// Both values are observed through the public Sort:
// - number: by hymn number the name sorts between the controls N-1 and N+1;
// - title: by title it sorts between the title without its last letter and the title plus a letter.
public class PowerPointSourceFilesTests
{
    private static string[] Sort(PowerPointSortOrder order, params string[] names) =>
        PowerPointSourceFiles.Sort(names, name => name + ".pptx", order).ToArray();

    [Theory]
    // The prefix ends the name (after the number, after "장", after a separator): the title is the whole name.
    // A hymnal prefix followed by "장" at the end of the name ("찬5장") is not covered: its "after" control
    // ("찬5장가") would itself parse as a hymn name with the title "가".
    [InlineData("40", 40, "40")]
    [InlineData("통일찬송가3", 3, "통일찬송가3")]
    [InlineData("40장", 40, "40장")]
    [InlineData("40_", 40, "40_")]
    // A separator after the number (lookahead branch): whitespace, U+3000, '_', '.', '-'.
    [InlineData("40 찬송으로 보답할 수 없는", 40, "찬송으로 보답할 수 없는")]
    [InlineData("9　평안", 9, "평안")]
    [InlineData("123_제목", 123, "제목")]
    [InlineData("7.축복", 7, "축복")]
    [InlineData("8-감사", 8, "감사")]
    // Leading whitespace, and a run of mixed separators after the number.
    [InlineData("  3_제목", 3, "제목")]
    [InlineData("5 _ 제목", 5, "제목")]
    // The "장" branch, with and without whitespace before it.
    [InlineData("1장_만복의 근원 하나님", 1, "만복의 근원 하나님")]
    [InlineData("40 장 찬송", 40, "찬송")]
    // Every hymnal prefix, with both branches ("장", then a separator).
    [InlineData("새찬송가 1장 만복", 1, "만복")]
    [InlineData("새찬송가12-제목", 12, "제목")]
    [InlineData("통일찬송가 2장_목소리", 2, "목소리")]
    [InlineData("통일찬송가 2 목소리", 2, "목소리")]
    [InlineData("찬송가 405장 주 하나님", 405, "주 하나님")]
    [InlineData("찬송가 405 주 하나님", 405, "주 하나님")]
    [InlineData("찬송 10장_전능", 10, "전능")]
    [InlineData("찬송 10_전능", 10, "전능")]
    [InlineData("찬151장(배경O)", 151, "(배경O)")]
    [InlineData("찬 7_축복", 7, "축복")]
    public void TheHymnNumberAndTitleAreReadFromTheNamePrefix(string name, int number, string title)
    {
        string below = $"{number - 1}장 x", above = $"{number + 1}장 x";
        Sort(PowerPointSortOrder.HymnNumber, above, name, below).Should().Equal(below, name, above);

        string before = title[..^1], after = title + "가";
        Sort(PowerPointSortOrder.Title, after, name, before).Should().Equal(before, name, after);
    }

    [Theory]
    // A letter right after the number (no separator, no "장"): no hymn number, the title is the whole name.
    [InlineData("40찬송")]
    [InlineData("12abc")]
    [InlineData("찬송40가")]
    // A prefix with no number.
    [InlineData("찬송가")]
    public void ANumberFollowedByALetterIsNotAHymnNumber(string name)
    {
        Sort(PowerPointSortOrder.HymnNumber, name, "99999장 x").Should().Equal("99999장 x", name);

        string before = name[..^1], after = name + "가";
        Sort(PowerPointSortOrder.Title, after, name, before).Should().Equal(before, name, after);
    }
}
